// Périmètre : dossiers ouverts, ou modifiés/clôturés depuis moins de 90 jours.
// Seuls les dossiers nouveaux ou modifiés depuis la dernière synchronisation sont relus en détail (quota noCRM : 2 000 requêtes/jour).
const J90 = 90 * 24 * 3600 * 1000;
const maintenant = Date.now();

const aplatir = (items) => items.flatMap(it => Array.isArray(it.json) ? it.json : [it.json]);

const commerciaux = {};
for (const u of aplatir($('noCRM – utilisateurs').all())) {
  if (u && u.id) commerciaux[u.id] = [u.firstname, u.lastname].filter(Boolean).join(' ');
}

const connus = {};
for (const it of $('Airtable – opportunités existantes').all()) {
  const f = it.json.fields || it.json;
  if (f && f.nocrm_id) connus[f.nocrm_id] = f['Modifié le'] ? Date.parse(f['Modifié le']) : 0;
}

const leads = aplatir($('noCRM – opportunités').all()).filter(l => l && l.id);
const sortie = [];
for (const l of leads) {
  const ouvert = l.status === 'todo' || l.status === 'standby';
  const reference = Date.parse(l.closed_at || l.updated_at || l.created_at);
  if (!ouvert && maintenant - reference > J90) continue;
  const modifie = Date.parse(l.updated_at);
  const dejaAJour = l.id in connus && Math.abs(connus[l.id] - modifie) < 1000;
  if (dejaAJour) continue;
  sortie.push({ json: { id: l.id, commercial: commerciaux[l.user_id] || '', nouveau: !(l.id in connus) } });
}
return sortie;

// Transforme chaque dossier noCRM en ligne Airtable. N'écrit QUE les champs « sync » :
// jamais Relance désactivée, Motif, Devis envoyé le ni Réponse client reçue le.
const STATUT = { todo: 'En cours', standby: 'En attente', won: 'Gagné', lost: 'Perdu', cancelled: 'Annulé' };
const commerciaux = {};
for (const s of $('Sélection des dossiers à mettre à jour').all()) commerciaux[s.json.id] = s.json.commercial;

const nombre = (s) => {
  if (s == null) return null;
  const n = parseFloat(String(s).replace(/[\s\u00a0\u202f]/g, '').replace(',', '.'));
  return Number.isFinite(n) ? n : null;
};
const RUE = /^(n°?\s*)?\d|\b(rue|avenue|av\.?|all[ée]e|chemin|bd|boulevard|impasse|place|cours|route|quai|lotissement|r[ée]sidence|lieu[- ]dit|passage|square|voie|parvis|esplanade)\b/i;
// Ville lue dans une adresse libre ; vide si illisible, jamais devinée.
const villeDe = (brut) => {
  let v = (brut || '').replace(/[\u{1F300}-\u{1FAFF}\u2600-\u27BF\uFE0F]/gu, '').replace(/\s+[—–-]\s+.*$/, '').trim();
  if (!v) return '';
  const fin = (s) => s.split(/\s{2,}/)[0].trim();
  let m = v.match(/\b\d{5}\s+([A-Za-zÀ-ÿ][^,\n(]*?)\s*(?:[,(]|$)/);
  if (m) return fin(m[1]);
  m = v.match(/([A-Za-zÀ-ÿ][A-Za-zÀ-ÿ'’\- ]*?)\s*\(\s*\d{5}\s*\)/);
  if (m) return fin(m[1]);
  m = v.match(/([A-Za-zÀ-ÿ][A-Za-zÀ-ÿ'’\- ]*?)\s+\d{5}\b/);
  if (m && !RUE.test(m[1])) return fin(m[1]);
  v = v.replace(/\([^)]*\)/g, '').trim();
  const segs = v.split(',').map(s => s.trim()).filter(Boolean);
  if (!segs.length) return '';
  // Nom de ville sans code postal : doit commencer par une majuscule (écarte « pas de logement », « à définir »…).
  const propre = (s) => !/\d/.test(s) && !RUE.test(s) && s.length <= 40 && /^[A-ZÀ-Ý]/.test(s);
  if (segs.length === 1) return propre(segs[0]) ? fin(segs[0]) : '';
  if (propre(segs[0])) return fin(segs[0]);
  const dernier = segs[segs.length - 1];
  return propre(dernier) ? fin(dernier) : '';
};
// Cherche « Départ : … » ; à défaut, la ligne qui suit « Ville de départ ».
const ville = (texte, sens) => {
  const lignes = texte.split(/\r?\n/).map(l => l.trim());
  const deuxPoints = sens === 'depart' ? /^d[ée]part\s*:\s*(.+)$/i : /^arriv[ée]e\s*:\s*(.+)$/i;
  const titre = sens === 'depart' ? /^ville\s+de\s+d[ée]part\s*:?$/i : /^ville\s+d.\s*arriv[ée]e\s*:?$/i;
  for (const l of lignes) {
    const m = l.match(deuxPoints);
    if (m) { const v = villeDe(m[1]); if (v) return v; break; }
  }
  const i = lignes.findIndex(l => titre.test(l));
  if (i >= 0) {
    const suivante = lignes.slice(i + 1).find(l => l.replace(/\u00a0/g, '').trim());
    if (suivante) return villeDe(suivante);
  }
  return '';
};
const date = (d) => (d ? new Date(d).toISOString() : null);

const lignes = [];
for (const it of $input.all()) {
  const l = it.json;
  if (!l || !l.id) continue;
  const ei = l.extended_info || {};
  const f = ei.fields || {};
  const desc = l.description || '';
  const vol = desc.match(/Volume de meuble\s*:\s*([\d.,]+)\s*m/i);
  const prix = [...desc.matchAll(/Prix Total\s*:\s*([\d\s\u00a0\u202f.,]+)€\s*TTC/gi)].map(m => nombre(m[1])).filter(n => n != null);
  const email = (f.email || ei.first_contact_email || '').trim();
  lignes.push({
    'Titre': l.title || '',
    'nocrm_id': l.id,
    'Prénom': f.first_name || '',
    'Nom': f.last_name || '',
    'E-mail': email || null,
    'Téléphone': f.phone || f.mobile || '',
    'Étape': l.step || null,
    'Statut': STATUT[l.status] || null,
    'Montant TTC': l.amount != null ? Number(l.amount) : null,
    'Commercial': commerciaux[l.id] || [ (ei.user || {}).firstname, (ei.user || {}).lastname ].filter(Boolean).join(' '),
    'Départ': ville(desc, 'depart'),
    'Arrivée': ville(desc, 'arrivee'),
    'Volume (m³)': vol ? nombre(vol[1]) : null,
    'Prix TTC extrait': prix.length ? Math.max(...prix) : null,
    'Prochaine action': date(l.next_action_at),
    'Créé le': date(l.created_at),
    'Modifié le': date(l.updated_at),
    'Clôturé le': date(l.closed_at),
    'Lien noCRM': ei.permalink || ('https://samdemenage.nocrm.io/leads/' + l.id),
    'Dernière sync': new Date().toISOString()
  });
}

// Lots de 10 : limite de l'API Airtable par requête.
const lots = [];
for (let i = 0; i < lignes.length; i += 10) {
  lots.push({ json: { records: lignes.slice(i, i + 10).map(fields => ({ fields })) } });
}
return lots;

// Met en forme l'alerte et calcule une clé de regroupement (nœud + message + heure).
const d = $json.execution || {};
const w = $json.workflow || {};
const noeud = d.lastNodeExecuted || 'inconnu';
const message = (d.error && (d.error.message || d.error.description)) || 'erreur sans message';
const quand = new Date().toLocaleString('fr-FR', { timeZone: 'Europe/Paris' });
const heure = new Date().toISOString().slice(0, 13);
const texte = [
  ':rotating_light: *Relances devis — échec d’exécution*',
  '*Bloc / workflow :* ' + (w.name || 'inconnu'),
  '*Nœud en échec :* ' + noeud,
  '*Message :* ' + String(message).slice(0, 800),
  '*Quand :* ' + quand,
  d.url ? '*Exécution :* ' + d.url : '*Exécution :* ' + (d.id || '—')
].join(String.fromCharCode(10));
return [{ json: { texte, cle: noeud + '|' + String(message).slice(0, 120) + '|' + heure } }];

// Construit la recherche Gmail des réponses : les mails reçus des clients en relance, sur 21 jours.
const aplatir = (items) => items.map(it => it.json.fields ? { id: it.json.id, ...it.json.fields } : it.json);
const emails = [...new Set(aplatir($('Airtable – dossiers en relance').all())
  .map(f => String(f['E-mail'] || '').trim().toLowerCase())
  .filter(e => /^[^@\s]+@[^@\s]+\.[a-z]{2,}$/.test(e)))];
// Aucune adresse : requête qui ne renvoie rien, plutôt qu'une recherche vide qui lirait toute la boîte.
const q = emails.length
  ? 'newer_than:21d {' + emails.map(e => 'from:' + e).join(' ') + '}'
  : 'from:aucun-client@invalid.invalid';
return [{ json: { q, nbAdresses: emails.length } }];

// Décide, dossier par dossier, s'il faut une relance aujourd'hui, et rédige le texte à partir du modèle validé.
// MODE : 'simulation' = relances créées « Simulée », rien n'est envoyé.
//        'reel'       = uniquement après déclaration explicite de Karim Bordeau (décision D5).
const MODE = 'simulation';
const TZ = 'Europe/Paris';
const NL = String.fromCharCode(10);

const ymd = (d) => new Intl.DateTimeFormat('fr-CA', { timeZone: TZ, year: 'numeric', month: '2-digit', day: '2-digit' }).format(d);
const plus = (jour, n) => { const [a, m, j] = jour.split('-').map(Number); return new Date(Date.UTC(a, m - 1, j + n)).toISOString().slice(0, 10); };
const ouvre = (jour) => { const js = new Date(jour + 'T12:00:00Z').getUTCDay(); return js === 6 ? plus(jour, 2) : js === 0 ? plus(jour, 1) : jour; };
const ecart = (a, b) => Math.round((Date.parse(b + 'T12:00:00Z') - Date.parse(a + 'T12:00:00Z')) / 864e5);
const adresses = (s) => (String(s || '').match(/[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Za-z]{2,}/g) || []).map(x => x.toLowerCase());
const aplatir = (items) => items.map(it => it.json.fields ? { id: it.json.id, ...it.json.fields } : it.json);
const aujourdhui = ymd(new Date());

// 1. Dernier envoi de devis par adresse client (pièce jointe nommée « Devis… », filtrée par la recherche Gmail).
const devis = {};
for (const it of $('Gmail – envois de devis').all()) {
  const m = it.json;
  if (!m || !m.id) continue;
  const quand = Number(m.internalDate);
  for (const a of adresses(m.To)) if (!devis[a] || quand > devis[a]) devis[a] = quand;
}

// 2. Réponses des clients : dates et extraits, par adresse.
const reponses = {};
for (const it of $('Gmail – réponses des clients').all()) {
  const m = it.json;
  if (!m || !m.id) continue;
  const de = adresses(m.From)[0];
  if (!de) continue;
  // Une réponse automatique (absence, accusé de réception) n'est pas une vraie réponse du client.
  if (/r[ée]ponse automatique|message d.absence|absent du bureau|absente du bureau|je suis absente?|out of office|automatic reply|auto.?reply|accus[ée] de r[ée]ception/i.test(String(m.Subject || '') + ' ' + String(m.snippet || '').slice(0, 120))) continue;
  (reponses[de] = reponses[de] || []).push({ quand: Number(m.internalDate), extrait: String(m.snippet || '') });
}

// 3. Relances déjà créées (ne jamais créer deux fois la même).
// Référence -> jour de création (ou, à défaut, date prévue), pour espacer R1 et R2.
const existantes = new Map();
for (const it of $('Airtable – relances existantes').all()) {
  const f = it.json.fields || it.json;
  const ref = f['Référence'];
  if (!ref) continue;
  const cree = it.json.createdTime || f['Prévue le'];
  existantes.set(ref, cree ? ymd(new Date(cree)) : aujourdhui);
}

// Rédaction : modèles validés le 16/09/2026 (annexe du cahier des charges).
const SIGNATURE = ["Secretariat - Sam'Déménage", 'Téléphone : 06 09 41 02 47', 'Mail : sandrine@samdemenage.fr', 'Mail contact : contact@samdemenage.fr'].join(NL);
const de_ = (v) => /^Le /.test(v) ? 'du ' + v.slice(3) : /^Les /.test(v) ? 'des ' + v.slice(4) : /^[AEIOUYÉÈÊÂÎH]/i.test(v) ? "d'" + v : 'de ' + v;
const a_ = (v) => /^Le /.test(v) ? 'au ' + v.slice(3) : /^Les /.test(v) ? 'aux ' + v.slice(4) : 'à ' + v;
const texte = (numero, prenom, dateDevis, depart, arrivee) => {
  const p = String(prenom || '').trim();
  const bonjour = p ? 'Bonjour ' + p.charAt(0).toUpperCase() + p.slice(1) + ',' : 'Bonjour,';
  const trajet = depart && arrivee
    ? (depart.toLowerCase() === arrivee.toLowerCase() ? ' pour votre déménagement ' + a_(arrivee) : ' pour votre déménagement ' + de_(depart) + ' ' + a_(arrivee))
    : '';
  if (numero === 'R1') return {
    objet: "Votre devis de déménagement Sam'Déménage",
    corps: [bonjour, '',
      'Je reviens vers vous au sujet du devis que nous vous avons adressé le ' + dateDevis + trajet + '.', '',
      "Avez-vous pu en prendre connaissance ? Si vous avez une question, ou si un point est à ajuster (date, volume, prestations), il vous suffit de répondre à ce message.", '',
      'Bien cordialement,', '', SIGNATURE, '',
      'Si votre projet a évolué et que vous ne souhaitez plus être recontacté, répondez simplement « stop ».'].join(NL)
  };
  return {
    objet: "Votre projet de déménagement est-il toujours d'actualité ?",
    corps: [bonjour, '',
      'Je me permets de revenir vers vous une dernière fois au sujet de notre devis du ' + dateDevis + trajet + '.', '',
      "Si la date vous convient toujours, une simple réponse nous permet de réserver l'équipe et le camion pour vous. Et si vous avez choisi une autre solution, un mot de votre part nous aide à clore votre dossier.", '',
      'Bien cordialement,', '', SIGNATURE, '',
      'Si vous ne souhaitez plus être recontacté, répondez simplement « stop ».'].join(NL)
  };
};

const sortie = [];
for (const f of aplatir($('Airtable – dossiers en relance').all())) {
  if (!f.id || !f.nocrm_id) continue;
  const email = String(f['E-mail'] || '').trim().toLowerCase();
  const envoiDevis = devis[email];
  if (!envoiDevis) continue; // devis introuvable : pas de relance (formule « Devis introuvable » dans Airtable)

  const maj = {};
  const connu = f['Devis envoyé le'] ? Date.parse(f['Devis envoyé le']) : 0;
  if (Math.abs(connu - envoiDevis) > 60000) maj['Devis envoyé le'] = new Date(envoiDevis).toISOString();

  const apres = (reponses[email] || []).filter(r => r.quand > envoiDevis).sort((a, b) => a.quand - b.quand);
  if (apres.length) {
    const premiere = new Date(apres[0].quand).toISOString();
    if (!f['Réponse client reçue le'] || Math.abs(Date.parse(f['Réponse client reçue le']) - apres[0].quand) > 60000) maj['Réponse client reçue le'] = premiere;
    if (apres.some(r => /\bstop\b/i.test(r.extrait))) { maj['Relance désactivée'] = true; maj['Motif de désactivation'] = 'Réponse stop du client'; }
  } else if (f['Réponse client reçue le']) {
    maj['Réponse client reçue le'] = null; // plus de vraie réponse après le dernier devis (réponse automatique écartée, devis renvoyé)
  }
  if (Object.keys(maj).length) sortie.push({ json: { cible: 'opportunite', id: f.id, fields: maj } });
  if (apres.length) continue; // le client a répondu : plus de relance

  const jourDevis = ymd(new Date(envoiDevis));
  const refBase = (f['Titre'] || 'Dossier') + ' · ' + f.nocrm_id;
  const enSequence = existantes.has(refBase + ' · R1');
  if (!enSequence && ecart(jourDevis, aujourdhui) > 7) continue; // D16 : au lancement, seuls les devis de moins de 7 jours entrent
  const dateDevis = new Intl.DateTimeFormat('fr-FR', { timeZone: TZ, day: 'numeric', month: 'long' }).format(new Date(envoiDevis));

  for (const [numero, libelle, jours, rattrapage] of [['R1', 'R1 · J+2', 2, 4], ['R2', 'R2 · J+7', 7, 6]]) {
    const prevue = ouvre(plus(jourDevis, jours));
    const ref = refBase + ' · ' + numero;
    if (aujourdhui < prevue || ecart(prevue, aujourdhui) > rattrapage || existantes.has(ref)) continue;
    if (numero === 'R2') {
      const jourR1 = existantes.get(refBase + ' · R1');
      if (!jourR1 || ecart(jourR1, aujourdhui) < 4) continue; // pas de R2 sans R1, ni moins de 4 jours après R1 (cas du rattrapage)
    }
    const t = texte(numero, f['Prénom'], dateDevis, f['Départ'], f['Arrivée']);
    sortie.push({ json: { cible: 'relance', fields: {
      'Référence': ref, 'Opportunité': [f.id], 'Numéro': libelle, 'Prévue le': prevue,
      'Destinataire': email, 'Objet': t.objet, 'Corps': t.corps,
      'Statut': MODE === 'simulation' ? 'Simulée' : 'Planifiée'
    } } });
  }
}
return sortie;

// Mises à jour des opportunités (dates de devis et de réponse, « stop »), par lots de 10.
const l = $input.all().filter(i => i.json.cible === 'opportunite').map(i => ({ id: i.json.id, fields: i.json.fields }));
const lots = [];
for (let i = 0; i < l.length; i += 10) lots.push({ json: { records: l.slice(i, i + 10) } });
return lots;

// Nouvelles relances, par lots de 10.
const l = $input.all().filter(i => i.json.cible === 'relance').map(i => ({ fields: i.json.fields }));
const lots = [];
for (let i = 0; i < l.length; i += 10) lots.push({ json: { records: l.slice(i, i + 10) } });
return lots;

// Tire au hasard l'heure d'envoi de chaque relance à planifier (décision D21, exigence F12).
// Fenêtre : jours ouvrés, 8 h – 17 h 30 (heure de Paris). Écart aléatoire de 7 à 25 min entre deux envois,
// jamais sur une heure ronde. Plafond quotidien ; le surplus attend le jour ouvré suivant.
const TZ = 'Europe/Paris';
const PLAFOND_PAR_JOUR = 20;
// Montée en charge (D21) : 5 relances par jour pendant 7 jours à partir du premier jour en conditions réelles.
// À renseigner au passage en conditions réelles (format 'AAAA-MM-JJ'). Vide = pas de montée en charge.
const DEBUT_CONDITIONS_REELLES = '';
const DEBUT_FENETRE = 8 * 60, FIN_FENETRE = 17 * 60 + 30;
const ECART_MIN = 7, ECART_MAX = 25;
const hasard = (a, b) => a + Math.random() * (b - a);

const parties = (d) => Object.fromEntries(new Intl.DateTimeFormat('en-GB', { timeZone: TZ, year: 'numeric', month: '2-digit', day: '2-digit', hour: '2-digit', minute: '2-digit', hour12: false, weekday: 'short' }).formatToParts(d).map(p => [p.type, p.value]));
const jourDe = (d) => { const p = parties(d); return p.year + '-' + p.month + '-' + p.day; };
const plus = (jour, n) => { const [a, m, j] = jour.split('-').map(Number); return new Date(Date.UTC(a, m - 1, j + n)).toISOString().slice(0, 10); };
const ouvre = (jour) => { const js = new Date(jour + 'T12:00:00Z').getUTCDay(); return js === 6 ? plus(jour, 2) : js === 0 ? plus(jour, 1) : jour; };
// (jour, minutes à Paris) -> instant réel, heure d'été comprise
const versInstant = (jour, minutes) => {
  const [a, m, j] = jour.split('-').map(Number);
  const essai = Date.UTC(a, m - 1, j, Math.floor(minutes / 60), Math.floor(minutes % 60), Math.floor((minutes % 1) * 60));
  const p = parties(new Date(essai));
  const affiche = Date.UTC(+p.year, +p.month - 1, +p.day, +p.hour % 24, +p.minute);
  return new Date(essai - (affiche - Math.floor(essai / 60000) * 60000));
};
const minutesParis = (d) => { const p = parties(d); return (+p.hour % 24) * 60 + (+p.minute); };

// Jour d'envoi : aujourd'hui si c'est un jour ouvré et qu'il reste au moins 30 min de fenêtre, sinon le jour ouvré suivant.
const maintenant = new Date();
const aujourdhui = jourDe(maintenant);
const jourOuvre = ouvre(aujourdhui) === aujourdhui;
const jourEnvoi = jourOuvre && minutesParis(maintenant) < FIN_FENETRE - 30 ? aujourdhui : ouvre(plus(aujourdhui, 1));
let plancher = jourEnvoi === aujourdhui ? Math.max(DEBUT_FENETRE, minutesParis(maintenant) + 10) : DEBUT_FENETRE;

// Créneaux déjà pris ce jour-là : ils comptent dans le plafond et on repart après le dernier.
let dejaPris = 0;
for (const it of $('Airtable – créneaux déjà pris').all()) {
  const f = it.json.fields || it.json;
  if (!f['Planifiée à']) continue;
  const d = new Date(f['Planifiée à']);
  if (jourDe(d) !== jourEnvoi) continue;
  dejaPris++;
  plancher = Math.max(plancher, minutesParis(d) + ECART_MIN);
}
const enMontee = DEBUT_CONDITIONS_REELLES && jourEnvoi >= DEBUT_CONDITIONS_REELLES && jourEnvoi < plus(DEBUT_CONDITIONS_REELLES, 7);
const capacite = Math.max(0, (enMontee ? 5 : PLAFOND_PAR_JOUR) - dejaPris);

// Relances à planifier, les plus anciennes d'abord.
const aPlanifier = $('Airtable – relances à planifier').all()
  .map(it => ({ id: it.json.id, ...(it.json.fields || it.json) }))
  .filter(r => r.id && r['Référence'])
  .sort((a, b) => String(a['Prévue le'] || '').localeCompare(String(b['Prévue le'] || '')));

// Tirage : écarts aléatoires, puis une heure de départ aléatoire qui laisse tenir toute la série dans la fenêtre.
let n = Math.min(capacite, aPlanifier.length);
let ecarts = [];
while (n > 0) {
  ecarts = Array.from({ length: n - 1 }, () => hasard(ECART_MIN, ECART_MAX));
  const duree = ecarts.reduce((s, e) => s + e, 0);
  if (plancher + duree <= FIN_FENETRE) break;
  n--; // la série ne tient pas : la dernière relance attendra le jour ouvré suivant
}
const lignes = [];
if (n > 0) {
  const duree = ecarts.reduce((s, e) => s + e, 0);
  let t = hasard(plancher, FIN_FENETRE - duree);
  for (let i = 0; i < n; i++) {
    if (i > 0) t += ecarts[i - 1];
    let minutes = t;
    if (Math.floor(minutes) % 15 === 0) minutes += hasard(1, 3); // jamais pile sur :00, :15, :30, :45
    lignes.push({ id: aPlanifier[i].id, fields: { 'Planifiée à': versInstant(jourEnvoi, Math.min(minutes, FIN_FENETRE)).toISOString() } });
  }
}
const lots = [];
for (let i = 0; i < lignes.length; i += 10) lots.push({ json: { records: lignes.slice(i, i + 10), jourEnvoi, planifiees: lignes.length, enAttente: aPlanifier.length - lignes.length } });
return lots;

// MODE : 'simulation' = aucun e-mail n'est envoyé ; chaque relance est seulement annotée (champ Motif).
//        'reel'       = envoi réel. À ne passer qu'après déclaration explicite de Karim Bordeau (décision D5),
//                       en même temps que MODE du nœud « Décision et rédaction des relances » (WF3)
//                       et DEBUT_CONDITIONS_REELLES du nœud « Tirage des heures d'envoi » (WF4).
return [{ json: { MODE: 'simulation' } }];

// Relances dont l'heure d'envoi tombe dans les 25 prochaines minutes (ou est passée), les plus tôt d'abord.
const MODE = $('Réglages WF5').first().json.MODE;
const relances = $input.all()
  .map(it => ({ id: it.json.id, ...(it.json.fields || it.json) }))
  .filter(r => r.id && r['Destinataire'] && r['Planifiée à'] && Array.isArray(r['Opportunité']) && r['Opportunité'].length)
  .sort((a, b) => String(a['Planifiée à']).localeCompare(String(b['Planifiée à'])))
  .map(r => ({ json: {
    id: r.id, reference: r['Référence'], destinataire: String(r['Destinataire']).trim(),
    objet: r['Objet'], corps: r['Corps'], planifieeA: r['Planifiée à'], opportunite: r['Opportunité'][0], MODE
  } }));
return relances;

// Verrou (exigence F1) : la prochaine exécution, 25 min plus tard, ne reprendra pas ces relances.
const MODE = $('Réglages WF5').first().json.MODE;
const l = $input.all().map(i => ({ id: i.json.id, fields: MODE === 'reel'
  ? { 'Statut': 'Envoi en cours' }
  : { 'Motif': "Simulation : en attente de l'heure d'envoi" } }));
const lots = [];
for (let i = 0; i < l.length; i += 10) lots.push({ json: { records: l.slice(i, i + 10) } });
return lots;

// Dernière vérification juste avant l'envoi (critère C5) : l'état noCRM à l'instant, le dossier Airtable,
// et une éventuelle réponse du client arrivée depuis la préparation du matin.
const r = $('Boucle – une relance à la fois').first().json;
const dossier = ($('Airtable – dossier de la relance').first().json.fields) || {};
const lead = $('noCRM – état du dossier').first().json || {};
const TZ = 'Europe/Paris';
const quand = (d) => new Intl.DateTimeFormat('fr-FR', { timeZone: TZ, day: '2-digit', month: '2-digit', hour: '2-digit', minute: '2-digit' }).format(new Date(d)).replace(' ', ' à ').replace(':', ' h ');
const AUTO = /r[ée]ponse automatique|message d.absence|absent du bureau|absente du bureau|je suis absente?|out of office|automatic reply|auto.?reply|accus[ée] de r[ée]ception/i;

let motif = '';
const devis = dossier['Devis envoyé le'] ? Date.parse(dossier['Devis envoyé le']) : 0;
if (Date.parse(r.planifieeA) < Date.now() - 24 * 3600 * 1000) {
  return [{ json: { action: 'replanifier', motif: '' } }]; // heure d'envoi dépassée de plus d'un jour : WF4 la replanifiera
}
if (!lead.id) motif = 'Vérification noCRM impossible';
else if (!['Devis envoyé', 'Trajets Axe Paris'].includes(lead.step)) motif = 'Étape changée dans noCRM (' + lead.step + ')';
else if (!['todo', 'standby'].includes(lead.status)) motif = 'Dossier clôturé dans noCRM (' + lead.status + ')';
else if (dossier['Relance désactivée']) motif = 'Relance désactivée' + (dossier['Motif de désactivation'] ? ' — ' + dossier['Motif de désactivation'] : '');
else if (dossier['Réponse client reçue le']) motif = 'Réponse du client reçue';
else {
  const reponse = $('Gmail – réponse récente du client').all().map(i => i.json)
    .filter(m => m && m.id && Number(m.internalDate) > devis && !AUTO.test(String(m.Subject || '') + ' ' + String(m.snippet || '').slice(0, 120)));
  if (reponse.length) motif = 'Réponse du client reçue le ' + quand(Number(reponse[0].internalDate));
}

const echec = motif === 'Vérification noCRM impossible';
if (r.MODE !== 'reel') {
  return [{ json: { action: 'simuler', motif: motif
    ? 'Simulation : aurait été annulée — ' + motif
    : 'Simulation : aurait été envoyée le ' + quand(r.planifieeA) + ' à ' + r.destinataire } }];
}
return [{ json: { action: motif ? (echec ? 'echec' : 'annuler') : 'envoyer', motif } }];

// Traduit le résultat en mise à jour de la relance dans Airtable.
const r = $('Boucle – une relance à la fois').first().json;
const d = $('Décision envoi').first().json;
const g = $input.first() ? $input.first().json : {};
let fields;
if (d.action === 'envoyer') {
  fields = g && g.id && !g.error
    ? { 'Statut': 'Envoyée', 'Envoyée le': new Date().toISOString(), 'Motif': null }
    : { 'Statut': 'Échec', 'Motif': 'Gmail a refusé l\u2019envoi : ' + String((g && g.error && (g.error.message || g.error)) || 'erreur inconnue').slice(0, 300) };
} else if (d.action === 'annuler') fields = { 'Statut': 'Annulée', 'Motif': d.motif };
else if (d.action === 'echec') fields = { 'Statut': 'Échec', 'Motif': d.motif };
else if (d.action === 'replanifier') fields = r.MODE === 'reel' ? { 'Statut': 'Planifiée', 'Planifiée à': null, 'Motif': null } : { 'Planifiée à': null, 'Motif': null };
else fields = { 'Motif': d.motif }; // simulation
return [{ json: { id: r.id, fields } }];

// Périmètre : dossiers ouverts, ou modifiés/clôturés depuis moins de 90 jours.
// Seuls les dossiers nouveaux ou modifiés depuis la dernière synchronisation sont relus en détail (quota noCRM : 2 000 requêtes/jour).
const J90 = 90 * 24 * 3600 * 1000;
const maintenant = Date.now();

const aplatir = (items) => items.flatMap(it => Array.isArray(it.json) ? it.json : [it.json]);

const commerciaux = {};
for (const u of aplatir($('noCRM – utilisateurs').all())) {
  if (u && u.id) commerciaux[u.id] = [u.firstname, u.lastname].filter(Boolean).join(' ');
}

const connus = {};
for (const it of $('Airtable – opportunités existantes').all()) {
  const f = it.json.fields || it.json;
  if (f && f.nocrm_id) connus[f.nocrm_id] = f['Modifié le'] ? Date.parse(f['Modifié le']) : 0;
}

const leads = aplatir($('noCRM – opportunités').all()).filter(l => l && l.id);
const sortie = [];
for (const l of leads) {
  const ouvert = l.status === 'todo' || l.status === 'standby';
  const reference = Date.parse(l.closed_at || l.updated_at || l.created_at);
  if (!ouvert && maintenant - reference > J90) continue;
  const modifie = Date.parse(l.updated_at);
  const dejaAJour = l.id in connus && Math.abs(connus[l.id] - modifie) < 1000;
  if (dejaAJour) continue;
  sortie.push({ json: { id: l.id, commercial: commerciaux[l.user_id] || '', nouveau: !(l.id in connus) } });
}
return sortie;

// Transforme chaque dossier noCRM en ligne Airtable. N'écrit QUE les champs « sync » :
// jamais Relance désactivée, Motif, Devis envoyé le ni Réponse client reçue le.
const STATUT = { todo: 'En cours', standby: 'En attente', won: 'Gagné', lost: 'Perdu', cancelled: 'Annulé' };
const commerciaux = {};
for (const s of $('Sélection des dossiers à mettre à jour').all()) commerciaux[s.json.id] = s.json.commercial;

const nombre = (s) => {
  if (s == null) return null;
  const n = parseFloat(String(s).replace(/[\s\u00a0\u202f]/g, '').replace(',', '.'));
  return Number.isFinite(n) ? n : null;
};
const RUE = /^(n°?\s*)?\d|\b(rue|avenue|av\.?|all[ée]e|chemin|bd|boulevard|impasse|place|cours|route|quai|lotissement|r[ée]sidence|lieu[- ]dit|passage|square|voie|parvis|esplanade)\b/i;
// Ville lue dans une adresse libre ; vide si illisible, jamais devinée.
const villeDe = (brut) => {
  let v = (brut || '').replace(/[\u{1F300}-\u{1FAFF}\u2600-\u27BF\uFE0F]/gu, '').replace(/\s+[—–-]\s+.*$/, '').trim();
  if (!v) return '';
  const fin = (s) => s.split(/\s{2,}/)[0].trim();
  let m = v.match(/\b\d{5}\s+([A-Za-zÀ-ÿ][^,\n(]*?)\s*(?:[,(]|$)/);
  if (m) return fin(m[1]);
  m = v.match(/([A-Za-zÀ-ÿ][A-Za-zÀ-ÿ'’\- ]*?)\s*\(\s*\d{5}\s*\)/);
  if (m) return fin(m[1]);
  m = v.match(/([A-Za-zÀ-ÿ][A-Za-zÀ-ÿ'’\- ]*?)\s+\d{5}\b/);
  if (m && !RUE.test(m[1])) return fin(m[1]);
  v = v.replace(/\([^)]*\)/g, '').trim();
  const segs = v.split(',').map(s => s.trim()).filter(Boolean);
  if (!segs.length) return '';
  // Nom de ville sans code postal : doit commencer par une majuscule (écarte « pas de logement », « à définir »…).
  const propre = (s) => !/\d/.test(s) && !RUE.test(s) && s.length <= 40 && /^[A-ZÀ-Ý]/.test(s);
  if (segs.length === 1) return propre(segs[0]) ? fin(segs[0]) : '';
  if (propre(segs[0])) return fin(segs[0]);
  const dernier = segs[segs.length - 1];
  return propre(dernier) ? fin(dernier) : '';
};
// Cherche « Départ : … » ; à défaut, la ligne qui suit « Ville de départ ».
const ville = (texte, sens) => {
  const lignes = texte.split(/\r?\n/).map(l => l.trim());
  const deuxPoints = sens === 'depart' ? /^d[ée]part\s*:\s*(.+)$/i : /^arriv[ée]e\s*:\s*(.+)$/i;
  const titre = sens === 'depart' ? /^ville\s+de\s+d[ée]part\s*:?$/i : /^ville\s+d.\s*arriv[ée]e\s*:?$/i;
  for (const l of lignes) {
    const m = l.match(deuxPoints);
    if (m) { const v = villeDe(m[1]); if (v) return v; break; }
  }
  const i = lignes.findIndex(l => titre.test(l));
  if (i >= 0) {
    const suivante = lignes.slice(i + 1).find(l => l.replace(/\u00a0/g, '').trim());
    if (suivante) return villeDe(suivante);
  }
  return '';
};
const date = (d) => (d ? new Date(d).toISOString() : null);

const lignes = [];
for (const it of $input.all()) {
  const l = it.json;
  if (!l || !l.id) continue;
  const ei = l.extended_info || {};
  const f = ei.fields || {};
  const desc = l.description || '';
  const vol = desc.match(/Volume de meuble\s*:\s*([\d.,]+)\s*m/i);
  const prix = [...desc.matchAll(/Prix Total\s*:\s*([\d\s\u00a0\u202f.,]+)€\s*TTC/gi)].map(m => nombre(m[1])).filter(n => n != null);
  const email = (f.email || ei.first_contact_email || '').trim();
  lignes.push({
    'Titre': l.title || '',
    'nocrm_id': l.id,
    'Prénom': f.first_name || '',
    'Nom': f.last_name || '',
    'E-mail': email || null,
    'Téléphone': f.phone || f.mobile || '',
    'Étape': l.step || null,
    'Statut': STATUT[l.status] || null,
    'Montant TTC': l.amount != null ? Number(l.amount) : null,
    'Commercial': commerciaux[l.id] || [ (ei.user || {}).firstname, (ei.user || {}).lastname ].filter(Boolean).join(' '),
    'Départ': ville(desc, 'depart'),
    'Arrivée': ville(desc, 'arrivee'),
    'Volume (m³)': vol ? nombre(vol[1]) : null,
    'Prix TTC extrait': prix.length ? Math.max(...prix) : null,
    'Prochaine action': date(l.next_action_at),
    'Créé le': date(l.created_at),
    'Modifié le': date(l.updated_at),
    'Clôturé le': date(l.closed_at),
    'Lien noCRM': ei.permalink || ('https://samdemenage.nocrm.io/leads/' + l.id),
    'Dernière sync': new Date().toISOString()
  });
}

// Lots de 10 : limite de l'API Airtable par requête.
const lots = [];
for (let i = 0; i < lignes.length; i += 10) {
  lots.push({ json: { records: lignes.slice(i, i + 10).map(fields => ({ fields })) } });
}
return lots;

// Met en forme l'alerte et calcule une clé de regroupement (nœud + message + heure).
const d = $json.execution || {};
const w = $json.workflow || {};
const noeud = d.lastNodeExecuted || 'inconnu';
const message = (d.error && (d.error.message || d.error.description)) || 'erreur sans message';
const quand = new Date().toLocaleString('fr-FR', { timeZone: 'Europe/Paris' });
const heure = new Date().toISOString().slice(0, 13);
const texte = [
  ':rotating_light: *Relances devis — échec d’exécution*',
  '*Bloc / workflow :* ' + (w.name || 'inconnu'),
  '*Nœud en échec :* ' + noeud,
  '*Message :* ' + String(message).slice(0, 800),
  '*Quand :* ' + quand,
  d.url ? '*Exécution :* ' + d.url : '*Exécution :* ' + (d.id || '—')
].join(String.fromCharCode(10));
return [{ json: { texte, cle: noeud + '|' + String(message).slice(0, 120) + '|' + heure } }];

// Construit la recherche Gmail des réponses : les mails reçus des clients en relance, sur 21 jours.
const aplatir = (items) => items.map(it => it.json.fields ? { id: it.json.id, ...it.json.fields } : it.json);
const emails = [...new Set(aplatir($('Airtable – dossiers en relance').all())
  .map(f => String(f['E-mail'] || '').trim().toLowerCase())
  .filter(e => /^[^@\s]+@[^@\s]+\.[a-z]{2,}$/.test(e)))];
// Aucune adresse : requête qui ne renvoie rien, plutôt qu'une recherche vide qui lirait toute la boîte.
const q = emails.length
  ? 'newer_than:21d {' + emails.map(e => 'from:' + e).join(' ') + '}'
  : 'from:aucun-client@invalid.invalid';
return [{ json: { q, nbAdresses: emails.length } }];

// Décide, dossier par dossier, s'il faut une relance aujourd'hui, et rédige le texte à partir du modèle validé.
// MODE : 'simulation' = relances créées « Simulée », rien n'est envoyé.
//        'reel'       = uniquement après déclaration explicite de Karim Bordeau (décision D5).
const MODE = 'simulation';
const TZ = 'Europe/Paris';
const NL = String.fromCharCode(10);

const ymd = (d) => new Intl.DateTimeFormat('fr-CA', { timeZone: TZ, year: 'numeric', month: '2-digit', day: '2-digit' }).format(d);
const plus = (jour, n) => { const [a, m, j] = jour.split('-').map(Number); return new Date(Date.UTC(a, m - 1, j + n)).toISOString().slice(0, 10); };
const ouvre = (jour) => { const js = new Date(jour + 'T12:00:00Z').getUTCDay(); return js === 6 ? plus(jour, 2) : js === 0 ? plus(jour, 1) : jour; };
const ecart = (a, b) => Math.round((Date.parse(b + 'T12:00:00Z') - Date.parse(a + 'T12:00:00Z')) / 864e5);
const adresses = (s) => (String(s || '').match(/[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Za-z]{2,}/g) || []).map(x => x.toLowerCase());
const aplatir = (items) => items.map(it => it.json.fields ? { id: it.json.id, ...it.json.fields } : it.json);
const aujourdhui = ymd(new Date());

// 1. Dernier envoi de devis par adresse client (pièce jointe nommée « Devis… », filtrée par la recherche Gmail).
const devis = {};
for (const it of $('Gmail – envois de devis').all()) {
  const m = it.json;
  if (!m || !m.id) continue;
  const quand = Number(m.internalDate);
  for (const a of adresses(m.To)) if (!devis[a] || quand > devis[a]) devis[a] = quand;
}

// 2. Réponses des clients : dates et extraits, par adresse.
const reponses = {};
for (const it of $('Gmail – réponses des clients').all()) {
  const m = it.json;
  if (!m || !m.id) continue;
  const de = adresses(m.From)[0];
  if (!de) continue;
  // Une réponse automatique (absence, accusé de réception) n'est pas une vraie réponse du client.
  if (/r[ée]ponse automatique|message d.absence|absent du bureau|absente du bureau|je suis absente?|out of office|automatic reply|auto.?reply|accus[ée] de r[ée]ception/i.test(String(m.Subject || '') + ' ' + String(m.snippet || '').slice(0, 120))) continue;
  (reponses[de] = reponses[de] || []).push({ quand: Number(m.internalDate), extrait: String(m.snippet || '') });
}

// 3. Relances déjà créées (ne jamais créer deux fois la même).
// Référence -> jour de création (ou, à défaut, date prévue), pour espacer R1 et R2.
const existantes = new Map();
for (const it of $('Airtable – relances existantes').all()) {
  const f = it.json.fields || it.json;
  const ref = f['Référence'];
  if (!ref) continue;
  const cree = it.json.createdTime || f['Prévue le'];
  existantes.set(ref, cree ? ymd(new Date(cree)) : aujourdhui);
}

// Rédaction : modèles validés le 16/09/2026 (annexe du cahier des charges).
const SIGNATURE = ["Secretariat - Sam'Déménage", 'Téléphone : 06 09 41 02 47', 'Mail : sandrine@samdemenage.fr', 'Mail contact : contact@samdemenage.fr'].join(NL);
const de_ = (v) => /^Le /.test(v) ? 'du ' + v.slice(3) : /^Les /.test(v) ? 'des ' + v.slice(4) : /^[AEIOUYÉÈÊÂÎH]/i.test(v) ? "d'" + v : 'de ' + v;
const a_ = (v) => /^Le /.test(v) ? 'au ' + v.slice(3) : /^Les /.test(v) ? 'aux ' + v.slice(4) : 'à ' + v;
const texte = (numero, prenom, dateDevis, depart, arrivee) => {
  const p = String(prenom || '').trim();
  const bonjour = p ? 'Bonjour ' + p.charAt(0).toUpperCase() + p.slice(1) + ',' : 'Bonjour,';
  const trajet = depart && arrivee
    ? (depart.toLowerCase() === arrivee.toLowerCase() ? ' pour votre déménagement ' + a_(arrivee) : ' pour votre déménagement ' + de_(depart) + ' ' + a_(arrivee))
    : '';
  if (numero === 'R1') return {
    objet: "Votre devis de déménagement Sam'Déménage",
    corps: [bonjour, '',
      'Je reviens vers vous au sujet du devis que nous vous avons adressé le ' + dateDevis + trajet + '.', '',
      "Avez-vous pu en prendre connaissance ? Si vous avez une question, ou si un point est à ajuster (date, volume, prestations), il vous suffit de répondre à ce message.", '',
      'Bien cordialement,', '', SIGNATURE, '',
      'Si votre projet a évolué et que vous ne souhaitez plus être recontacté, répondez simplement « stop ».'].join(NL)
  };
  return {
    objet: "Votre projet de déménagement est-il toujours d'actualité ?",
    corps: [bonjour, '',
      'Je me permets de revenir vers vous une dernière fois au sujet de notre devis du ' + dateDevis + trajet + '.', '',
      "Si la date vous convient toujours, une simple réponse nous permet de réserver l'équipe et le camion pour vous. Et si vous avez choisi une autre solution, un mot de votre part nous aide à clore votre dossier.", '',
      'Bien cordialement,', '', SIGNATURE, '',
      'Si vous ne souhaitez plus être recontacté, répondez simplement « stop ».'].join(NL)
  };
};

const sortie = [];
for (const f of aplatir($('Airtable – dossiers en relance').all())) {
  if (!f.id || !f.nocrm_id) continue;
  const email = String(f['E-mail'] || '').trim().toLowerCase();
  const envoiDevis = devis[email];
  if (!envoiDevis) continue; // devis introuvable : pas de relance (formule « Devis introuvable » dans Airtable)

  const maj = {};
  const connu = f['Devis envoyé le'] ? Date.parse(f['Devis envoyé le']) : 0;
  if (Math.abs(connu - envoiDevis) > 60000) maj['Devis envoyé le'] = new Date(envoiDevis).toISOString();

  const apres = (reponses[email] || []).filter(r => r.quand > envoiDevis).sort((a, b) => a.quand - b.quand);
  if (apres.length) {
    const premiere = new Date(apres[0].quand).toISOString();
    if (!f['Réponse client reçue le'] || Math.abs(Date.parse(f['Réponse client reçue le']) - apres[0].quand) > 60000) maj['Réponse client reçue le'] = premiere;
    if (apres.some(r => /\bstop\b/i.test(r.extrait))) { maj['Relance désactivée'] = true; maj['Motif de désactivation'] = 'Réponse stop du client'; }
  } else if (f['Réponse client reçue le']) {
    maj['Réponse client reçue le'] = null; // plus de vraie réponse après le dernier devis (réponse automatique écartée, devis renvoyé)
  }
  if (Object.keys(maj).length) sortie.push({ json: { cible: 'opportunite', id: f.id, fields: maj } });
  if (apres.length) continue; // le client a répondu : plus de relance

  const jourDevis = ymd(new Date(envoiDevis));
  const refBase = (f['Titre'] || 'Dossier') + ' · ' + f.nocrm_id;
  const enSequence = existantes.has(refBase + ' · R1');
  if (!enSequence && ecart(jourDevis, aujourdhui) > 7) continue; // D16 : au lancement, seuls les devis de moins de 7 jours entrent
  const dateDevis = new Intl.DateTimeFormat('fr-FR', { timeZone: TZ, day: 'numeric', month: 'long' }).format(new Date(envoiDevis));

  for (const [numero, libelle, jours, rattrapage] of [['R1', 'R1 · J+2', 2, 4], ['R2', 'R2 · J+7', 7, 6]]) {
    const prevue = ouvre(plus(jourDevis, jours));
    const ref = refBase + ' · ' + numero;
    if (aujourdhui < prevue || ecart(prevue, aujourdhui) > rattrapage || existantes.has(ref)) continue;
    if (numero === 'R2') {
      const jourR1 = existantes.get(refBase + ' · R1');
      if (!jourR1 || ecart(jourR1, aujourdhui) < 4) continue; // pas de R2 sans R1, ni moins de 4 jours après R1 (cas du rattrapage)
    }
    const t = texte(numero, f['Prénom'], dateDevis, f['Départ'], f['Arrivée']);
    sortie.push({ json: { cible: 'relance', fields: {
      'Référence': ref, 'Opportunité': [f.id], 'Numéro': libelle, 'Prévue le': prevue,
      'Destinataire': email, 'Objet': t.objet, 'Corps': t.corps,
      'Statut': MODE === 'simulation' ? 'Simulée' : 'Planifiée'
    } } });
  }
}
return sortie;

// Mises à jour des opportunités (dates de devis et de réponse, « stop »), par lots de 10.
const l = $input.all().filter(i => i.json.cible === 'opportunite').map(i => ({ id: i.json.id, fields: i.json.fields }));
const lots = [];
for (let i = 0; i < l.length; i += 10) lots.push({ json: { records: l.slice(i, i + 10) } });
return lots;

// Nouvelles relances, par lots de 10.
const l = $input.all().filter(i => i.json.cible === 'relance').map(i => ({ fields: i.json.fields }));
const lots = [];
for (let i = 0; i < l.length; i += 10) lots.push({ json: { records: l.slice(i, i + 10) } });
return lots;

// Tire au hasard l'heure d'envoi de chaque relance à planifier (décision D21, exigence F12).
// Fenêtre : jours ouvrés, 8 h – 17 h 30 (heure de Paris). Écart aléatoire de 7 à 25 min entre deux envois,
// jamais sur une heure ronde. Plafond quotidien ; le surplus attend le jour ouvré suivant.
const TZ = 'Europe/Paris';
const PLAFOND_PAR_JOUR = 20;
// Montée en charge (D21) : 5 relances par jour pendant 7 jours à partir du premier jour en conditions réelles.
// À renseigner au passage en conditions réelles (format 'AAAA-MM-JJ'). Vide = pas de montée en charge.
const DEBUT_CONDITIONS_REELLES = '';
const DEBUT_FENETRE = 8 * 60, FIN_FENETRE = 17 * 60 + 30;
const ECART_MIN = 7, ECART_MAX = 25;
const hasard = (a, b) => a + Math.random() * (b - a);

const parties = (d) => Object.fromEntries(new Intl.DateTimeFormat('en-GB', { timeZone: TZ, year: 'numeric', month: '2-digit', day: '2-digit', hour: '2-digit', minute: '2-digit', hour12: false, weekday: 'short' }).formatToParts(d).map(p => [p.type, p.value]));
const jourDe = (d) => { const p = parties(d); return p.year + '-' + p.month + '-' + p.day; };
const plus = (jour, n) => { const [a, m, j] = jour.split('-').map(Number); return new Date(Date.UTC(a, m - 1, j + n)).toISOString().slice(0, 10); };
const ouvre = (jour) => { const js = new Date(jour + 'T12:00:00Z').getUTCDay(); return js === 6 ? plus(jour, 2) : js === 0 ? plus(jour, 1) : jour; };
// (jour, minutes à Paris) -> instant réel, heure d'été comprise
const versInstant = (jour, minutes) => {
  const [a, m, j] = jour.split('-').map(Number);
  const essai = Date.UTC(a, m - 1, j, Math.floor(minutes / 60), Math.floor(minutes % 60), Math.floor((minutes % 1) * 60));
  const p = parties(new Date(essai));
  const affiche = Date.UTC(+p.year, +p.month - 1, +p.day, +p.hour % 24, +p.minute);
  return new Date(essai - (affiche - Math.floor(essai / 60000) * 60000));
};
const minutesParis = (d) => { const p = parties(d); return (+p.hour % 24) * 60 + (+p.minute); };

// Jour d'envoi : aujourd'hui si c'est un jour ouvré et qu'il reste au moins 30 min de fenêtre, sinon le jour ouvré suivant.
const maintenant = new Date();
const aujourdhui = jourDe(maintenant);
const jourOuvre = ouvre(aujourdhui) === aujourdhui;
const jourEnvoi = jourOuvre && minutesParis(maintenant) < FIN_FENETRE - 30 ? aujourdhui : ouvre(plus(aujourdhui, 1));
let plancher = jourEnvoi === aujourdhui ? Math.max(DEBUT_FENETRE, minutesParis(maintenant) + 10) : DEBUT_FENETRE;

// Créneaux déjà pris ce jour-là : ils comptent dans le plafond et on repart après le dernier.
let dejaPris = 0;
for (const it of $('Airtable – créneaux déjà pris').all()) {
  const f = it.json.fields || it.json;
  if (!f['Planifiée à']) continue;
  const d = new Date(f['Planifiée à']);
  if (jourDe(d) !== jourEnvoi) continue;
  dejaPris++;
  plancher = Math.max(plancher, minutesParis(d) + ECART_MIN);
}
const enMontee = DEBUT_CONDITIONS_REELLES && jourEnvoi >= DEBUT_CONDITIONS_REELLES && jourEnvoi < plus(DEBUT_CONDITIONS_REELLES, 7);
const capacite = Math.max(0, (enMontee ? 5 : PLAFOND_PAR_JOUR) - dejaPris);

// Relances à planifier, les plus anciennes d'abord.
const aPlanifier = $('Airtable – relances à planifier').all()
  .map(it => ({ id: it.json.id, ...(it.json.fields || it.json) }))
  .filter(r => r.id && r['Référence'])
  .sort((a, b) => String(a['Prévue le'] || '').localeCompare(String(b['Prévue le'] || '')));

// Tirage : écarts aléatoires, puis une heure de départ aléatoire qui laisse tenir toute la série dans la fenêtre.
let n = Math.min(capacite, aPlanifier.length);
let ecarts = [];
while (n > 0) {
  ecarts = Array.from({ length: n - 1 }, () => hasard(ECART_MIN, ECART_MAX));
  const duree = ecarts.reduce((s, e) => s + e, 0);
  if (plancher + duree <= FIN_FENETRE) break;
  n--; // la série ne tient pas : la dernière relance attendra le jour ouvré suivant
}
const lignes = [];
if (n > 0) {
  const duree = ecarts.reduce((s, e) => s + e, 0);
  let t = hasard(plancher, FIN_FENETRE - duree);
  for (let i = 0; i < n; i++) {
    if (i > 0) t += ecarts[i - 1];
    let minutes = t;
    if (Math.floor(minutes) % 15 === 0) minutes += hasard(1, 3); // jamais pile sur :00, :15, :30, :45
    lignes.push({ id: aPlanifier[i].id, fields: { 'Planifiée à': versInstant(jourEnvoi, Math.min(minutes, FIN_FENETRE)).toISOString() } });
  }
}
const lots = [];
for (let i = 0; i < lignes.length; i += 10) lots.push({ json: { records: lignes.slice(i, i + 10), jourEnvoi, planifiees: lignes.length, enAttente: aPlanifier.length - lignes.length } });
return lots;

// MODE : 'simulation' = aucun e-mail n'est envoyé ; chaque relance est seulement annotée (champ Motif).
//        'reel'       = envoi réel. À ne passer qu'après déclaration explicite de Karim Bordeau (décision D5),
//                       en même temps que MODE du nœud « Décision et rédaction des relances » (WF3)
//                       et DEBUT_CONDITIONS_REELLES du nœud « Tirage des heures d'envoi » (WF4).
return [{ json: { MODE: 'simulation' } }];

// Relances dont l'heure d'envoi tombe dans les 25 prochaines minutes (ou est passée), les plus tôt d'abord.
const MODE = $('Réglages WF5').first().json.MODE;
const relances = $input.all()
  .map(it => ({ id: it.json.id, ...(it.json.fields || it.json) }))
  .filter(r => r.id && r['Destinataire'] && r['Planifiée à'] && Array.isArray(r['Opportunité']) && r['Opportunité'].length)
  .sort((a, b) => String(a['Planifiée à']).localeCompare(String(b['Planifiée à'])))
  .map(r => ({ json: {
    id: r.id, reference: r['Référence'], destinataire: String(r['Destinataire']).trim(),
    objet: r['Objet'], corps: r['Corps'], planifieeA: r['Planifiée à'], opportunite: r['Opportunité'][0], MODE
  } }));
return relances;

// Verrou (exigence F1) : la prochaine exécution, 25 min plus tard, ne reprendra pas ces relances.
const MODE = $('Réglages WF5').first().json.MODE;
const l = $input.all().map(i => ({ id: i.json.id, fields: MODE === 'reel'
  ? { 'Statut': 'Envoi en cours' }
  : { 'Motif': "Simulation : en attente de l'heure d'envoi" } }));
const lots = [];
for (let i = 0; i < l.length; i += 10) lots.push({ json: { records: l.slice(i, i + 10) } });
return lots;

// Dernière vérification juste avant l'envoi (critère C5) : l'état noCRM à l'instant, le dossier Airtable,
// et une éventuelle réponse du client arrivée depuis la préparation du matin.
const r = $('Boucle – une relance à la fois').first().json;
const dossier = ($('Airtable – dossier de la relance').first().json.fields) || {};
const lead = $('noCRM – état du dossier').first().json || {};
const TZ = 'Europe/Paris';
const quand = (d) => new Intl.DateTimeFormat('fr-FR', { timeZone: TZ, day: '2-digit', month: '2-digit', hour: '2-digit', minute: '2-digit' }).format(new Date(d)).replace(' ', ' à ').replace(':', ' h ');
const AUTO = /r[ée]ponse automatique|message d.absence|absent du bureau|absente du bureau|je suis absente?|out of office|automatic reply|auto.?reply|accus[ée] de r[ée]ception/i;

let motif = '';
const devis = dossier['Devis envoyé le'] ? Date.parse(dossier['Devis envoyé le']) : 0;
if (Date.parse(r.planifieeA) < Date.now() - 24 * 3600 * 1000) {
  return [{ json: { action: 'replanifier', motif: '' } }]; // heure d'envoi dépassée de plus d'un jour : WF4 la replanifiera
}
if (!lead.id) motif = 'Vérification noCRM impossible';
else if (!['Devis envoyé', 'Trajets Axe Paris'].includes(lead.step)) motif = 'Étape changée dans noCRM (' + lead.step + ')';
else if (!['todo', 'standby'].includes(lead.status)) motif = 'Dossier clôturé dans noCRM (' + lead.status + ')';
else if (dossier['Relance désactivée']) motif = 'Relance désactivée' + (dossier['Motif de désactivation'] ? ' — ' + dossier['Motif de désactivation'] : '');
else if (dossier['Réponse client reçue le']) motif = 'Réponse du client reçue';
else {
  const reponse = $('Gmail – réponse récente du client').all().map(i => i.json)
    .filter(m => m && m.id && Number(m.internalDate) > devis && !AUTO.test(String(m.Subject || '') + ' ' + String(m.snippet || '').slice(0, 120)));
  if (reponse.length) motif = 'Réponse du client reçue le ' + quand(Number(reponse[0].internalDate));
}

const echec = motif === 'Vérification noCRM impossible';
if (r.MODE !== 'reel') {
  return [{ json: { action: 'simuler', motif: motif
    ? 'Simulation : aurait été annulée — ' + motif
    : 'Simulation : aurait été envoyée le ' + quand(r.planifieeA) + ' à ' + r.destinataire } }];
}
return [{ json: { action: motif ? (echec ? 'echec' : 'annuler') : 'envoyer', motif } }];

// Traduit le résultat en mise à jour de la relance dans Airtable.
const r = $('Boucle – une relance à la fois').first().json;
const d = $('Décision envoi').first().json;
const g = $input.first() ? $input.first().json : {};
let fields;
if (d.action === 'envoyer') {
  fields = g && g.id && !g.error
    ? { 'Statut': 'Envoyée', 'Envoyée le': new Date().toISOString(), 'Motif': null }
    : { 'Statut': 'Échec', 'Motif': 'Gmail a refusé l\u2019envoi : ' + String((g && g.error && (g.error.message || g.error)) || 'erreur inconnue').slice(0, 300) };
} else if (d.action === 'annuler') fields = { 'Statut': 'Annulée', 'Motif': d.motif };
else if (d.action === 'echec') fields = { 'Statut': 'Échec', 'Motif': d.motif };
else if (d.action === 'replanifier') fields = r.MODE === 'reel' ? { 'Statut': 'Planifiée', 'Planifiée à': null, 'Motif': null } : { 'Planifiée à': null, 'Motif': null };
else fields = { 'Motif': d.motif }; // simulation
return [{ json: { id: r.id, fields } }];
